        ncl={(y+shift,x) for y,x in cl}
        colored.append((v,ncl))
    for y in range(h):
        for x in range(w):
            if any(y in [(a,b)[0] for a,b in c] for _,c in colored): pass
    for v,ncl in colored:
        for y,x in ncl: out[y][x]=v
    ws=[x for x in range(w) if any(out[y][x]!=bg for y in range(h))]
    w_=max(ws)+1
    return [r_[:w_] for r_ in out]
